                        '**부서별 선택**: `👥수신·참조`·`🔗공유` 창은 **조직도(2026 대림 조직도 및 업무분장 Ver.3.0)** 부서별로 사람을 보여 줍니다. 위의 부서 버튼(경영진·연구혁신팀·품질경영팀·생산공급망팀·디지털전략팀·영업전략팀·경영지원팀)을 누르면 그 부서만 보이고, 부서 줄(예: `생산공급망팀 · 본사 포장부`)의 체크로 **부서 전체**를 한 번에 결재자·참조·공유로 넣습니다. 이름 옆에 직위·담당 업무가 보이고, 아직 앱에 가입하지 않은 사람은 `미가입`(고를 수 없음)으로 표시됩니다(`미가입자도 보기`를 끄면 숨김). 조직도에 없는 가입자는 맨 아래 `조직도 밖`에 나옵니다.',
                        '`👥수신·참조`에서 **결재자(수신)**와 **참조**를 고르고 `저장하고 알리기`를 누르면, 수신자는 **할일(결재 요청)과 1:1 메시지**, 참조자는 1:1 메시지를 받습니다. 수신에서 빼면 그 사람의 결재 요청 할일도 지워집니다.',
                        '`🔗공유`는 고른 사람에게 문서를 알리는 메시지를 보냅니다.',
                        '받은 사람은 `전자결재` → **수신·참조 문서함**에서 문서를 보고 `열기`로 그 문서 화면에 가서 결재 칸에 서명합니다. 결재 칸 아래에 `수신 ○○ · 참조 ○○` 요약이 보입니다.',
                        '**첨언**: `💬첨언`을 누르면 그 문서의 검토 의견 목록이 열립니다. 의견을 적고 `첨언 남기기`를 누르면 결재·수신·참조·공유 관련자에게 메시지로 알립니다(끌 수 있음). 첨언은 조회 전용·경영자·참조·공유받은 사람 모두 쓸 수 있고, 내가 쓴 첨언만 지웁니다. 전자결재 문서함의 줄마다 `💬` 버튼으로도 봅니다.',
                        '**반려**: 결재자가 `⛔반려`를 누르고 사유를 적으면 결재 칸 아래에 빨간 **반려** 표시(반려자·날짜·사유)가 나오고 관련자에게 메시지가 갑니다. 반려된 문서는 **재상신 전까지 아무도 서명할 수 없습니다**(이미 받은 서명은 남음). 보완한 뒤 `↩재상신`을 누르고 메모를 적으면 반려가 풀립니다. 반려·재상신 기록은 첨언 목록에 남고, 인쇄물 결재 칸 아래에도 반려 사유가 나옵니다.',
                        '**참조·공유로 받은 사람은 검토·첨언만** 합니다: 결재 칸 서명·반려를 할 수 없고, 결재 칸 아래에 `👀 참조·공유로 받은 문서 — 검토·첨언만` 안내가 보입니다. 결재(서명)를 받아야 하는 사람은 **수신**으로 지정하세요.',
                        '`📎첨부`는 그 문서의 **첨부파일** 창을 엽니다. 파일을 끌어 놓거나 `파일 첨부`로 올리고(1개 20MB까지), 이름을 누르면 열고, ⬇로 받습니다. 첨부는 생산·구매계획서, 요청서, 업무추진계획서, 업무일지, 수불부, 전표, 카드사용내역, **보고서 메뉴의 모든 보고서**, 품질 검사 기록에 붙일 수 있고, A4 인쇄물 끝에 첨부 목록이 들어갑니다.'
