                        '넘어온 오늘 작성일자에 `+ 줄 추가`로 새 스케줄을 넣습니다. 다른 날짜를 직접 만들려면 `작성 일자`를 고르고 `새 작성일자`를 누르면 **가장 최근 스케줄이 복사**됩니다.',
