                        '`2주`·`4주`·`8주`로 기간을 고르고 `◀` `▶`(1주씩), `오늘`로 옮깁니다. 주말·공휴일은 회색, 오늘은 빨간 세로선입니다.',
                        '**막대** = 생산 기간(생산 시작~완료일, 없으면 포장계획일 하루, 생산중이면 오늘까지), 색은 상태(보류·예정·부자재 준비·생산중·완료·출고완료). **◆** = 납품예정일(지남 빨강·7일 안 주황), **🚚** = 출고일, 옅은 선 = 수주일~납품예정일. 막대가 납품예정일을 넘기면 빨간 테두리입니다.',
