                        '`웹 저장소`에서 제품을 검색(초성 검색 가능)·종류별로 골라 `불러오기` 합니다.',
                        '편집 모드에서 거래처·구분·제품명·1~10번 항목을 칸을 눌러 적고, 사진 칸을 눌러 고르거나 끌어다 놓거나 붙여넣기(Ctrl+V)로 넣습니다. `엑셀 불러오기`·`엑셀 뷰어`의 표준서 적용·구글시트 연동으로 1~10번 항목을 한 번에 채울 수도 있습니다. 이때 **시트에 놓인 사진도 엑셀과 같은 자리에 자동으로 들어갑니다** — `완성 제품 및 부자재 이미지` 아래 사진은 왼쪽부터 용기 → 라벨 → 인박스 → 아웃박스 순서로 넣고(본문에 `없음`이라고 적은 칸은 건너뜁니다), 본문 표 오른쪽의 사진은 위에 적힌 제목대로 식별 스티커·파렛트 칸에 넣습니다. 사진 칸의 `변경`을 누르면 나오는 이미지 창의 `웹 저장소 사진` 탭에서 **파일 저장소에 등록한 품목 사진**을 품목코드·품명으로 찾아 `적용`으로 바꿀 수도 있습니다. 자리를 정하지 못한 사진은 `엑셀 추출 이미지` 목록에서 골라 넣으세요. 구글 시트에서 **셀 안에 삽입한 그림**은 가져오지 못하니 `셀 위에 삽입`으로 넣어 두세요.',
