            summary: '포장부 종이 양식 **초·중·종물 검사 및 작업일지**를 앱에서 씁니다. 작업장·날짜마다 한 장이며, 기준중량 계산·중량 이탈 표시·전자결재(작성·검토·부서장)·A4 인쇄를 하고, 불량 수량은 품질관리 공정 불량 기록으로 이어집니다.',
