                        '**새 날짜를 열면 그 날 제품생산/입고로 등록한 완제품**(제품·용량·원액·제품 LOT·양품·작업자)이 작업 줄로 자동으로 채워집니다. 저장 뒤에 생산입고가 더 생기면 `생산입고 반영`을 누르면 아직 없는 LOT만 줄로 더합니다.',
