                        '초물·중물·종물마다 중량을 **3회** 넣습니다. 기준중량 ± 허용 범위(기본 2%, 오른쪽 위에서 바꿈) 안이면 초록, 벗어나면 **빨간색**입니다. 상태 확인(씰링·라벨·박스)은 OK/NG로 고릅니다.',
