                    tips: ['**불량 수량**을 넣은 줄은 저장할 때 **품질관리 → 공정관리 불량 기록**으로 함께 남습니다(검사수량 = 양품 + 불량, 상태 NG가 있으면 조건부 합격). 다시 저장하면 같은 기록이 고쳐지고, 불량을 지우거나 줄을 지우면 그 기록도 지워집니다.'],
