                        '`사용 원료 및 부자재 자동 차감`을 켜 두면 배합비에 따라 원료·부자재 소요량이 자동 계산됩니다. 각 줄의 **재고/차감후** 수량을 확인하고 필요하면 고칩니다.',
                        '원료·부자재 줄의 **창고**: `김포공장 (창고 미지정)`처럼 **거점만 고르면 그 거점의 재고 전체**를 봅니다. 거점 단위 재고를 먼저 쓰고 모자라면 같은 거점의 창고·구획 재고에서 나눠 꺼내며, 어느 창고에서 얼마를 꺼내는지 `차감: 김포공장(창고 미지정) 980L + 김포1B 220L`처럼 보여 줍니다. **창고를 직접 고르면 그 창고 재고만** 씁니다.',
                        '원료·부자재 줄의 품명은 드롭다운 위 **검색칸**에 품명 일부(예: `드럼`, `캡`, `5W30`)를 치면 후보가 뜹니다. 눌러서(또는 ↑↓ 후 Enter) 고르면 드롭다운이 그 품목으로 바뀝니다.',
