                        '`불량품에 들어간 원료·부자재도 차감`을 켜 두면(기본) 원료·부자재 사용량이 **양품 + 불량** 수량 기준으로 계산됩니다(불량품에 쓴 용기·원액도 빠져나감).',
                        '`업무일지·초·중·종물 검사·포장수율표에도 같이 반영`(기본 켬)이면 완제품은 제조일자·입고 거점의 업무일지 `제품포장작업`(재고 반영됨 표시)·초·중·종물 작업 줄·포장수율표 포장 줄에, **라벨부착**은 포장수율표 `라벨작업` 줄에도 들어갑니다(라벨부착의 업무일지 라벨부착작업 줄은 아래 옵션으로 따로 넣음).',
